function fmtInt(n) {
  if (n === null || n === undefined || Number.isNaN(Number(n))) return "—";
  const s = Math.round(Number(n)).toString();
  return s.replace(/\B(?=(\d{3})+(?!\d))/g, " ");
}

function fmtPct(x) {
  if (x === null || x === undefined || Number.isNaN(Number(x))) return "—";
  const v = Number(x);
  return (Math.round(v * 10) / 10).toString(); // 1 знак после запятой
}

function fmtNum(x) {
  if (x === null || x === undefined || Number.isNaN(Number(x))) return "—";
  const v = Number(x);
  // для ИЦ часто удобно 1 знак, но можно и как есть
  return (Math.round(v * 10) / 10).toString();
}

const root = $json;
const resp = root.response;

const reportDate = new Date().toLocaleDateString("ru-RU");

const stats = {
  channel_title: resp.title ?? "—",
  username: resp.username ?? "—",
  report_date: reportDate,

  subs_total: fmtInt(resp.participants_count),
  avg_post_reach: fmtInt(resp.avg_post_reach),

  err: fmtPct(resp.err_percent),
  err24: fmtPct(resp.err24_percent),

  ad12: fmtInt(resp.adv_post_reach_12h),
  ad24: fmtInt(resp.adv_post_reach_24h),
  ad48: fmtInt(resp.adv_post_reach_48h),

  citation_index: fmtNum(resp.ci_index),
  citation_channels: fmtInt(resp.mentioning_channels_count),
  mentions: fmtInt(resp.mentions_count),
  reposts: fmtInt(resp.forwards_count),

  posts_count: fmtInt(resp.posts_count),
};

const text =
`📊 <b>Статистика Telegram-канала ${stats.channel_title} (${stats.report_date})</b>

Канал уверенно растёт и показывает стабильные рекламные показатели в нише 18+ с живой, вовлечённой аудиторией.

🔹 Подписчики: ${stats.subs_total}

🔹 Охваты:
— средний охват поста: ${stats.avg_post_reach}
— ERR ${stats.err}% — высокий уровень видимости контента
— ERR₍24₎ ${stats.err24}% — сильный интерес в первые сутки

🔹 Рекламные показатели:
— ${stats.ad12} просмотров за 12 часов
— ${stats.ad24} просмотров за 24 часа
— ${stats.ad48} просмотров за 48 часов
➡️ реклама добирает охват со временем, а не “проседает” после публикации

🔹 Цитируемость и распространение:
— индекс цитирования: ${stats.citation_index}
— ${stats.citation_channels} канала(ов) упоминают канал
— ${stats.mentions} упоминаний и ${stats.reposts} репостов
➡️ контент активно расходится по Telegram

🔹 Возраст канала: ${ Math.round(
  DateTime.now()
    .diff(DateTime.fromISO('2025-09-17'), 'months')
    .months
) } месяцев
➡️ молодая аудитория без выгорания и рекламной слепоты`;

return [{ json: { text, stats, raw: resp } }];
